import { useState } from 'react';
import type { KeyboardEvent } from 'react';
import {
  Screen,
  Card,
  Grid,
  Stack,
  Row,
  TextField,
  SelectField,
  Button,
  Badge,
  Alert,
  KeyBar,
} from '@nexti/ds';

type Errors = {
  txtCuentaOrigen?: string;
  txtCuentaDestino?: string;
  txtMonto?: string;
};

type Status = 'idle' | 'error' | 'success';

const TIPO_OPTIONS = [
  { value: '', label: 'Sin especificar' },
  { value: 'PRO', label: 'Programada (PRO)' },
  { value: 'INM', label: 'Inmediata (INM)' },
];

function parseMonto(raw: string): number {
  return Number(raw.replace(',', '.'));
}

function validate(origen: string, destino: string, monto: string): Errors {
  const errors: Errors = {};

  if (origen.trim() === '') {
    errors.txtCuentaOrigen = 'Ingrese la cuenta origen';
  } else if (!/^\d{10}$/.test(origen)) {
    errors.txtCuentaOrigen = 'La cuenta tiene 10 dígitos';
  }

  if (destino.trim() === '') {
    errors.txtCuentaDestino = 'Ingrese la cuenta destino';
  }

  if (monto.trim() === '') {
    errors.txtMonto = 'Ingrese el monto';
  } else {
    const n = parseMonto(monto);
    if (Number.isNaN(n) || n < 1 || n > 10000) {
      errors.txtMonto = 'El monto va de 1 a 10.000';
    }
  }

  return errors;
}

export default function TransferenciaEntreCuentas({
  navigate,
}: {
  navigate: (to: string) => void;
}) {
  const [origen, setOrigen] = useState('');
  const [destino, setDestino] = useState('');
  const [monto, setMonto] = useState('');
  const [tipo, setTipo] = useState('');

  const [errors, setErrors] = useState<Errors>({});
  const [status, setStatus] = useState<Status>('idle');
  const [comision, setComision] = useState('');
  const [mensaje, setMensaje] = useState('');

  const transferir = () => {
    const found = validate(origen, destino, monto);
    setErrors(found);

    if (Object.keys(found).length > 0) {
      setStatus('error');
      setComision('');
      setMensaje('No se pudo realizar la transferencia. Revise los campos marcados.');
      return;
    }

    setStatus('success');
    // Valor de ejemplo para el prototipo: la regla de cálculo real vive en btnTransferir_Click
    setComision('USD 2,50');
    setMensaje('Transferencia realizada correctamente. Puede ver el comprobante.');
  };

  const cancelar = () => {
    // El sistema original navega a Inicio, que no forma parte de este prototipo:
    // aquí se limpia el formulario.
    setOrigen('');
    setDestino('');
    setMonto('');
    setTipo('');
    setErrors({});
    setComision('');
    setMensaje('Operación cancelada. En el sistema original se vuelve a Inicio.');
    setStatus('idle');
  };

  const onKeyDown = (e: KeyboardEvent<HTMLDivElement>) => {
    const target = e.target as HTMLElement;
    if (e.key === 'Enter' && target.tagName !== 'BUTTON') {
      e.preventDefault();
      transferir();
    }
  };

  return (
    <Screen
      title="Transferencia entre cuentas"
      code="SCR-TRANSFERENCIA"
      keys={
        <KeyBar
          actions={[
            { key: 'ENTER', label: 'Transferir', onPress: transferir, primary: true },
            { key: 'PF3', label: 'Cancelar', onPress: cancelar },
          ]}
        />
      }
    >
      <div onKeyDown={onKeyDown}>
        <Stack>
          <Card title="Datos de la transferencia">
            <Stack>
              <Grid columns={2}>
                <div data-field="txtCuentaOrigen">
                  <TextField
                    label="Cuenta origen"
                    required
                    numeric
                    maxLength={10}
                    hint="10 dígitos"
                    error={errors.txtCuentaOrigen}
                    value={origen}
                    onChange={(v: string) => setOrigen(v.replace(/\D/g, '').slice(0, 10))}
                  />
                </div>

                <div data-field="txtCuentaDestino">
                  <TextField
                    label="Cuenta destino"
                    required
                    numeric
                    maxLength={10}
                    error={errors.txtCuentaDestino}
                    value={destino}
                    onChange={(v: string) => setDestino(v.replace(/\D/g, '').slice(0, 10))}
                  />
                </div>

                <div data-field="txtMonto">
                  <TextField
                    label="Monto (USD)"
                    required
                    numeric
                    maxLength={9}
                    hint="Entre 1 y 10.000"
                    error={errors.txtMonto}
                    value={monto}
                    onChange={(v: string) => setMonto(v.replace(/[^\d.,]/g, '').slice(0, 9))}
                  />
                </div>

                <div data-field="ddlTipo">
                  <SelectField
                    label="Tipo"
                    options={TIPO_OPTIONS}
                    value={tipo}
                    onChange={(v: string) => setTipo(v)}
                  />
                </div>
              </Grid>
            </Stack>
          </Card>

          <Card title="Resultado">
            <Stack>
              <Row>
                <strong>Comisión:</strong>
                <span data-field="lblComision">
                  {comision !== '' ? <Badge>{comision}</Badge> : <span>—</span>}
                </span>
              </Row>

              <div data-field="lblMensaje" aria-live="polite">
                {status === 'error' && <Alert tone="error">{mensaje}</Alert>}
                {status === 'success' && <Alert tone="success">{mensaje}</Alert>}
                {status === 'idle' && mensaje !== '' && <Alert tone="info">{mensaje}</Alert>}
                {status === 'idle' && mensaje === '' && (
                  <span>Complete los datos y presione Transferir.</span>
                )}
              </div>
            </Stack>
          </Card>

          <Row>
            <Button variant="primary" shortcut="ENTER" onClick={transferir}>
              Transferir
            </Button>
            <Button variant="secondary" shortcut="PF3" onClick={cancelar}>
              Cancelar
            </Button>
            {status === 'success' && (
              <Button variant="ghost" onClick={() => navigate('SCR-COMPROBANTE')}>
                Ver comprobante
              </Button>
            )}
          </Row>
        </Stack>
      </div>
    </Screen>
  );
}
