import { useState } from 'react'
import type { FormEvent } from 'react'
import {
  Screen,
  Card,
  Grid,
  Stack,
  Row,
  TextField,
  SelectField,
  Button,
  Badge,
  Alert,
} from '@nexti/ds'
import { ApiError } from '../api/client'
import type { ScreenProps } from './types'

type Errors = {
  txtCuentaOrigen?: string
  txtCuentaDestino?: string
  txtMonto?: string
}

type Status = 'idle' | 'error' | 'success'

const TIPO_OPTIONS = [
  { value: '', label: 'Sin especificar' },
  { value: 'PRO', label: 'Programada (PRO)' },
  { value: 'INM', label: 'Inmediata (INM)' },
]

function parseMonto(raw: string): number {
  return Number(raw.trim().replace(',', '.'))
}

function validate(origen: string, destino: string, monto: string): Errors {
  const errors: Errors = {}

  if (origen.trim() === '') {
    errors.txtCuentaOrigen = 'Ingrese la cuenta origen'
  }

  if (destino.trim() === '') {
    errors.txtCuentaDestino = 'Ingrese la cuenta destino'
  }

  if (monto.trim() === '') {
    errors.txtMonto = 'Ingrese el monto'
  } else if (Number.isNaN(parseMonto(monto))) {
    errors.txtMonto = 'El monto no es válido'
  }

  return errors
}

export default function TransferenciaScreen({ api }: ScreenProps) {
  const [origen, setOrigen] = useState('')
  const [destino, setDestino] = useState('')
  const [monto, setMonto] = useState('')
  const [tipo, setTipo] = useState('')

  const [errors, setErrors] = useState<Errors>({})
  const [status, setStatus] = useState<Status>('idle')
  const [comision, setComision] = useState('')
  const [mensaje, setMensaje] = useState('')
  const [busy, setBusy] = useState(false)

  const transferir = async () => {
    const found = validate(origen, destino, monto)
    setErrors(found)

    if (Object.keys(found).length > 0) {
      setStatus('error')
      setComision('')
      setMensaje('No se pudo realizar la transferencia. Revise los campos marcados.')
      return
    }

    setBusy(true)
    try {
      const response = await api.transferFunds({
        origen: origen.trim(),
        destino: destino.trim(),
        monto: parseMonto(monto),
        tipo,
      })
      setStatus('success')
      setComision(response.comision.toFixed(2))
      setMensaje(response.mensaje)
    } catch (e) {
      setStatus('error')
      setComision('')
      setMensaje(
        e instanceof ApiError ? e.message : 'No se pudo realizar la transferencia.',
      )
    } finally {
      setBusy(false)
    }
  }

  const onSubmit = (e: FormEvent<HTMLFormElement>) => {
    e.preventDefault()
    void transferir()
  }

  const cancelar = () => {
    setOrigen('')
    setDestino('')
    setMonto('')
    setTipo('')
    setErrors({})
    setComision('')
    setMensaje('')
    setStatus('idle')
  }

  return (
    <Screen title="Transferencia entre cuentas" code="SCR-TRANSFERENCIA">
      <form onSubmit={onSubmit} noValidate>
        <Stack>
          <Card title="Datos de la transferencia">
            <Stack>
              <Grid columns={2}>
                <div data-field="txtCuentaOrigen">
                  <TextField
                    label="Cuenta origen"
                    required
                    maxLength={10}
                    hint="10 dígitos"
                    error={errors.txtCuentaOrigen}
                    value={origen}
                    onChange={(v: string) => setOrigen(v.slice(0, 10))}
                  />
                </div>

                <div data-field="txtCuentaDestino">
                  <TextField
                    label="Cuenta destino"
                    required
                    maxLength={10}
                    error={errors.txtCuentaDestino}
                    value={destino}
                    onChange={(v: string) => setDestino(v.slice(0, 10))}
                  />
                </div>

                <div data-field="txtMonto">
                  <TextField
                    label="Monto (USD)"
                    required
                    numeric
                    maxLength={9}
                    hint="Entre 1 y 10.000"
                    error={errors.txtMonto}
                    value={monto}
                    onChange={(v: string) => setMonto(v.slice(0, 9))}
                  />
                </div>

                <div data-field="ddlTipo">
                  <SelectField
                    label="Tipo"
                    options={TIPO_OPTIONS}
                    value={tipo}
                    onChange={(v: string) => setTipo(v)}
                  />
                </div>
              </Grid>
            </Stack>
          </Card>

          <Card title="Resultado">
            <Stack>
              <Row>
                <strong>Comisión:</strong>
                <span data-field="lblComision">
                  {comision !== '' ? <Badge>{comision}</Badge> : <span>—</span>}
                </span>
              </Row>

              <div data-field="lblMensaje" aria-live="polite">
                {status === 'error' && <Alert tone="error">{mensaje}</Alert>}
                {status === 'success' && <Alert tone="success">{mensaje}</Alert>}
                {status === 'idle' && mensaje !== '' && <Alert tone="info">{mensaje}</Alert>}
                {status === 'idle' && mensaje === '' && (
                  <span>Complete los datos y presione Transferir.</span>
                )}
              </div>
            </Stack>
          </Card>

          <Row>
            <Button
              type="submit"
              variant="primary"
              data-action="ENTER"
              disabled={busy}
            >
              Transferir
            </Button>
            <Button
              type="button"
              variant="secondary"
              data-action="btnCancelar"
              onClick={cancelar}
            >
              Cancelar
            </Button>
          </Row>
        </Stack>
      </form>
    </Screen>
  )
}
